package com.pawkeys.keyboard

import android.content.Context
import android.media.AudioAttributes
import android.media.AudioManager
import android.media.SoundPool
import android.os.Build
import android.os.VibrationEffect
import android.os.Vibrator
import android.os.VibratorManager
import kotlin.random.Random

/**
 * Key sound and haptics. Sounds: "click", "kitten", "cat", "duck" (generated by
 * tools/make_sounds.py) or "system" (the phone's own keyboard sounds).
 */
class Feedback(context: Context, private val prefs: Prefs) {
    private val audio = context.getSystemService(AudioManager::class.java)
    private val vibrator: Vibrator? = if (Build.VERSION.SDK_INT >= 31) {
        context.getSystemService(VibratorManager::class.java)?.defaultVibrator
    } else {
        @Suppress("DEPRECATION")
        context.getSystemService(Vibrator::class.java)
    }
    private val pool = SoundPool.Builder()
        .setMaxStreams(4)
        .setAudioAttributes(
            AudioAttributes.Builder()
                .setUsage(AudioAttributes.USAGE_ASSISTANCE_SONIFICATION)
                .setContentType(AudioAttributes.CONTENT_TYPE_SONIFICATION)
                .build()
        ).build()
    private val sounds = mapOf(
        "click" to pool.load(context, R.raw.key_click, 1),
        "kitten" to pool.load(context, R.raw.key_kitten, 1),
        "cat" to pool.load(context, R.raw.key_cat, 1),
        "duck" to pool.load(context, R.raw.key_duck, 1),
    )

    fun onKey(code: Int) {
        if (prefs.vibrate) vibrate(prefs.vibrateMs.toLong())
        if (prefs.sound) play(code)
    }

    private fun play(code: Int) {
        val style = prefs.soundStyle
        val id = sounds[style]
        if (id == null) {
            val fx = when (code) {
                Codes.DELETE -> AudioManager.FX_KEYPRESS_DELETE
                Codes.SPACE -> AudioManager.FX_KEYPRESS_SPACEBAR
                Codes.ENTER -> AudioManager.FX_KEYPRESS_RETURN
                else -> AudioManager.FX_KEYPRESS_STANDARD
            }
            audio?.playSoundEffect(fx, -1f)
            return
        }
        // Lower voices for the big keys, and a little variation so typing doesn't sound robotic.
        val base = when (code) {
            Codes.DELETE -> 0.88f
            Codes.SPACE -> 0.93f
            Codes.ENTER -> 0.84f
            else -> 1f
        }
        val rate = (base * (0.95f + Random.nextFloat() * 0.1f)).coerceIn(0.5f, 2f)
        val volume = prefs.soundVolume / 100f
        pool.play(id, volume, volume, 1, 0, rate)
    }

    fun tick() {
        if (prefs.vibrate) vibrate(maxOf(5L, prefs.vibrateMs / 2L))
    }

    /** Plays a sample of [style] (used when choosing a sound). */
    fun preview(style: String) {
        val id = sounds[style] ?: return
        pool.play(id, prefs.soundVolume / 100f, prefs.soundVolume / 100f, 1, 0, 1f)
    }

    private fun vibrate(ms: Long) {
        val v = vibrator ?: return
        if (!v.hasVibrator()) return
        runCatching { v.vibrate(VibrationEffect.createOneShot(ms, VibrationEffect.DEFAULT_AMPLITUDE)) }
    }

    fun release() = pool.release()

    companion object {
        /** Order the Den's Sound tile cycles through ("off" = silent). */
        val STYLES = listOf("off", "click", "kitten", "cat", "duck")
        fun label(style: String) = when (style) {
            "click" -> "Click"; "kitten" -> "Kitten"; "cat" -> "Cat"; "duck" -> "Duck"; "system" -> "System"; else -> "Silent"
        }
    }
}
